public class Main {
    public static void main(String[] args) {
        System.out.println("1. Source Code: Main.java");
        System.out.println("2. Compiler: javac Main.java -> Main.class (Bytecode)");
        System.out.println("3. Virtual Machine: java Main -> Native Machine Code");
    }
}

public class Main {
